// Try a few keys
var allKitchenKeys = Object.keys(lc).filter(function(k){
  var canvases = lc[k];
  return (canvases||[]).some(function(c){return c.id && c.id.indexOf('diana_morning')>-1;});
});
var diags = {};
allKitchenKeys.forEach(function(k){
  var picks = s.selectAutoFireCanvasForLocation(k);
  diags[k] = {
    pick_id: picks && picks.id,
    pick_name: picks && picks.name,
    isNew: picks ? s.isCanvasNew(picks.id) : null,
    locationHasNew: s.locationHasNewCanvases(k),
    npcsHere: s.getNpcsWithCanvasesAtLocation(k).map(function(n){return n.name;}),
  };
});
return JSON.stringify({time: sv.game_state.time_state, kitchen_keys: allKitchenKeys, diags: diags});

var s = SugarCube.setup;
var sv = SugarCube.State.variables;
var helpData = s.help_data || {};
var lc = helpData.locationCanvases || {};
var locKeys = Object.keys(lc);
// Build map locKey -> {name?, canvas_count, autoFire pick, locationHasNew}
var report = {};
locKeys.slice(0,40).forEach(function(k){
  var canvases = lc[k] || [];
  var pick = s.selectAutoFireCanvasForLocation(k);
  report[k] = {
    canvas_count: canvases.length,
    autoFire_pick: pick ? {id: pick.id, name: pick.name || pick.passageName, repeatable: pick.isRepeatable} : null,
    locationHasNew: s.locationHasNewCanvases(k),
    npcs_at: s.getNpcsWithCanvasesAtLocation(k).map(function(n){return n.name;}),
  };
});
return JSON.stringify({location_count: locKeys.length, report: report});
